"use client"

/**
 * Inline Edit (Notchset) v1.0.0 · Notchset
 * Docs: https://notchset.dev/components/inline-edit
 * MIT licensed: free to use, change and share.
 */

import * as React from "react"

import { cn } from "@/lib/utils"
import { Announcer, Spinner, useTimeline } from "@/lib/notchset/shared"
import { useControllable } from "@/lib/notchset/field"
import { typedSound, useSound } from "@/lib/notchset/sound"

/*
 * Inline Edit: a title you edit in place. The input has the same type and padding as the title, so
 * nothing moves when it opens. Enter or leaving the field saves (a spinner, then a check that pops in),
 * Esc rewinds, an empty title shakes and stays open, an unchanged one closes quietly.
 */

type EditState = "view" | "edit" | "saving" | "saved"

interface InlineEditProps extends Omit<React.ComponentPropsWithoutRef<"div">, "defaultValue" | "onChange" | "onError"> {
  value?: string | undefined
  defaultValue?: string | undefined
  onValueChange?: ((value: string) => void) | undefined
  /** Saves a changed title. Return a promise: the check shows only when it resolves. */
  onSave?: ((value: string) => unknown) | undefined
  onError?: ((error: unknown) => void) | undefined
  /** Called as the success state shows (after the work resolves and the minimum time), so anything that follows the button lands with it. */
  onSuccess?: (() => void) | undefined
  /** The accessible name of the field, e.g. "Project name". */
  label: string
  sound?: boolean | undefined
}

const InlineEdit = React.forwardRef<HTMLDivElement, InlineEditProps>(function InlineEdit(
  { value, defaultValue = "", onValueChange, onSave, onError, onSuccess, label, sound = true, className, ...props },
  ref
) {
  const { sfx } = useSound(sound)
  const timeline = useTimeline()
  const [title, setTitle] = useControllable(value, defaultValue, onValueChange)
  const [state, setState] = React.useState<EditState>("view")
  const [draft, setDraft] = React.useState(title)
  const [shakes, setShakes] = React.useState(0)
  const [hover, setHover] = React.useState(false)
  const input = React.useRef<HTMLInputElement>(null)
  const trigger = React.useRef<HTMLButtonElement>(null)
  const committing = React.useRef(false)
  const hintId = React.useId()

  React.useEffect(() => {
    if (state !== "edit") return
    input.current?.focus()
    input.current?.select()
  }, [state])

  const open = () => {
    sfx.tick()
    setDraft(title)
    setState("edit")
  }

  const commit = async () => {
    if (committing.current || state !== "edit") return
    const next = draft.trim()
    if (!next) {
      sfx.buzz()
      setShakes((n) => n + 1)
      input.current?.focus()
      return
    }
    if (next === title) {
      setState("view")
      return
    }
    committing.current = true
    const previous = title
    setTitle(next)
    setState("saving")
    try {
      await onSave?.(next)
    } catch (error) {
      committing.current = false
      setTitle(previous)
      sfx.buzz()
      setShakes((n) => n + 1)
      setDraft(next)
      setState("edit")
      onError?.(error)
      return
    }
    committing.current = false
    sfx.chime()
    onSuccess?.()
    setState("saved")
    timeline.after(1800, () => setState((s) => (s === "saved" ? "view" : s)))
  }

  const cancel = () => {
    sfx.noise(0.25, 0.05, 2600, 500)
    setDraft(title)
    setState("view")
    requestAnimationFrame(() => trigger.current?.focus())
  }

  const editing = state === "edit"
  return (
    <div ref={ref} data-slot="inline-edit" data-notchset="" className={cn("flex flex-col gap-1.5", className)} {...props}>
      <div className={cn("flex min-h-[46px] items-center gap-2", shakes > 0 && (shakes % 2 ? "animate-[ns-shake_.42s]" : "animate-[ns-shake-b_.42s]"))}>
        {editing ? (
          <input
            ref={input}
            value={draft}
            aria-label={label}
            aria-describedby={hintId}
            onChange={(event) => {
              typedSound(sfx, draft, event.target.value)
              setDraft(event.target.value)
            }}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing) return
              if (event.key === "Enter") {
                event.preventDefault()
                void commit()
              } else if (event.key === "Escape") {
                event.preventDefault()
                cancel()
              }
            }}
            onBlur={() => void commit()}
            className="-ms-2.5 min-w-0 flex-1 rounded-[min(var(--radius),12px)] border-0 bg-[var(--background)] px-2.5 py-1 text-[26px] leading-[1.3] font-semibold tracking-[-0.03em] text-[var(--foreground)] shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_50%,var(--input)),0_0_0_5px_color-mix(in_oklab,var(--foreground)_7%,transparent)] outline-none"
          />
        ) : (
          <button
            ref={trigger}
            type="button"
            aria-label={`${label}: ${title}. Edit`}
            onClick={open}
            onPointerEnter={() => setHover(true)}
            onPointerLeave={() => setHover(false)}
            className="-ms-2.5 flex min-w-0 cursor-text items-center gap-2.5 rounded-[min(var(--radius),12px)] px-2.5 py-1 text-start text-[26px] leading-[1.3] font-semibold tracking-[-0.03em] text-[var(--foreground)] outline-none [transition:background-color_.2s] hover:bg-[var(--accent)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]"
          >
            <span className="min-w-0 truncate">{title}</span>
            <svg
              viewBox="0 0 24 24"
              aria-hidden="true"
              className={cn("size-4 shrink-0 text-[var(--muted-foreground)] [transition:opacity_.2s,transform_.35s_var(--ns-ease-pop),scale_.35s_var(--ns-ease-pop),translate_.35s_var(--ns-ease-pop),rotate_.35s_var(--ns-ease-pop)]", hover ? "translate-x-0 opacity-100" : "-translate-x-1 opacity-0 rtl:translate-x-1")}
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z" />
            </svg>
          </button>
        )}
        <span aria-hidden="true" className="grid size-[18px] shrink-0 place-items-center">
          {state === "saving" && <Spinner />}
          {state === "saved" && (
            <span className="grid size-[18px] animate-[ns-chip_.4s_var(--ns-ease-rebound)_both] place-items-center rounded-full bg-[var(--foreground)] text-[var(--background)]">
              <svg viewBox="0 0 24 24" className="size-3" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                <path d="M20 6 9 17l-5-5" />
              </svg>
            </span>
          )}
        </span>
      </div>
      <p id={hintId} className={cn("m-0 font-mono text-[11px] text-[var(--muted-foreground)] [transition:opacity_.2s]", editing ? "opacity-100" : "opacity-0")}>
        ↵ save · esc cancel
      </p>
      <Announcer message={state === "saved" ? "Saved" : ""} />
    </div>
  )
})

export { InlineEdit, type InlineEditProps }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * Text fields' shared parts: the label whose focus dot slides in, the shell that carries the
 * border, the focus ring, the error state and the shake, the helper line, and controlled-or-not value
 * state. Every class is a plain literal so the shadcn CLI can prefix it.
 */

/** Value state that works controlled (value) or uncontrolled (defaultValue), reporting every change. */
function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (next: T) => void) {
  const [inner, setInner] = React.useState(defaultValue)
  const current = value === undefined ? inner : value
  const set = React.useCallback(
    (next: T) => {
      if (value === undefined) setInner(next)
      onChange?.(next)
    },
    [value, onChange]
  )
  return [current, set] as const
}

/** Focus tracking for a field: within the shell, so inner buttons keep the focused look. */
function useFocusWithin() {
  const [focused, setFocused] = React.useState(false)
  const props = {
    onFocus: () => setFocused(true),
    onBlur: (event: React.FocusEvent<HTMLElement>) => {
      if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setFocused(false)
    },
  }
  return [focused, props] as const
}

/** The label with the 6px focus dot that slides in before it while the field has focus. */
function FieldLabel({ htmlFor, id, focused, children, aside, className }: { htmlFor?: string | undefined; id?: string | undefined; focused: boolean; children: React.ReactNode; aside?: React.ReactNode | undefined; className?: string | undefined }) {
  return (
    <div data-slot="field-label" className={cn("flex min-h-[18px] items-center justify-between gap-2", className)}>
      <label htmlFor={htmlFor} id={id} className="flex items-center text-[length:var(--ns-type-label)] font-medium text-[var(--foreground)]">
        <span
          aria-hidden="true"
          className={cn(
            "block h-1.5 shrink-0 rounded-full bg-[var(--foreground)] [transition:width_.35s_var(--ns-ease-reshape),margin_.35s_var(--ns-ease-reshape),transform_.4s_var(--ns-ease-rebound),scale_.4s_var(--ns-ease-rebound),translate_.4s_var(--ns-ease-rebound),rotate_.4s_var(--ns-ease-rebound)]",
            focused ? "me-2 w-1.5 scale-100" : "me-0 w-0 scale-0"
          )}
        />
        {children}
      </label>
      {aside}
    </div>
  )
}

/**
 * The field's outline: 44px pill by default. Focus darkens the border and adds a soft ring; invalid
 * turns both destructive. Changing `shake` replays the error shake.
 */
const FieldShell = React.forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div"> & { focused: boolean; invalid?: boolean | undefined; shake?: number | undefined }>(function FieldShell(
  { focused, invalid = false, shake = 0, className, ...props },
  ref
) {
  return (
    <div
      ref={ref}
      data-slot="field-shell"
      data-focused={focused || undefined}
      data-invalid={invalid || undefined}
      className={cn(
        "relative flex h-[var(--ns-control-field)] items-center gap-2 rounded-[var(--radius)] border bg-[var(--background)] ps-4 pe-1.5 text-[var(--foreground)] [transition:border-color_.2s,box-shadow_var(--ns-time-state)]",
        invalid && "border-[var(--destructive)] shadow-[0_0_0_4px_color-mix(in_oklab,var(--destructive)_14%,transparent)]",
        !invalid && focused && "border-[color:var(--ns-focus-color,color-mix(in_oklab,var(--foreground)_55%,var(--input)))] shadow-[0_0_0_4px_color-mix(in_oklab,var(--foreground)_7%,transparent)]",
        !invalid && !focused && "border-[var(--input)] shadow-[0_0_0_0_transparent]",
        // Two identical keyframes, alternated: a new name restarts the shake without remounting the input.
        shake > 0 && (shake % 2 ? "animate-[ns-shake_.42s]" : "animate-[ns-shake-b_.42s]"),
        className
      )}
      {...props}
    />
  )
})

/** The helper line under a field (12px muted; destructive when it reports an error). */
function FieldHelper({ id, tone = "muted", children, className }: { id?: string | undefined; tone?: "muted" | "error" | "strong" | undefined; children: React.ReactNode; className?: string | undefined }) {
  return (
    <p
      id={id}
      data-slot="field-helper"
      className={cn(
        "m-0 min-h-4 text-[length:var(--ns-type-note)] leading-[var(--ns-leading-note)]",
        tone === "error" ? "text-[var(--destructive)]" : tone === "strong" ? "text-[var(--foreground)]" : "text-[var(--muted-foreground)]",
        className
      )}
    >
      {children}
    </p>
  )
}

/** A 30px ghost button inside a shell that keeps the input focused when pressed. */
const FieldIconButton = React.forwardRef<HTMLButtonElement, React.ComponentPropsWithoutRef<"button">>(function FieldIconButton({ className, onMouseDown, ...props }, ref) {
  return (
    <button
      ref={ref}
      type="button"
      onMouseDown={(event) => {
        event.preventDefault()
        onMouseDown?.(event)
      }}
      className={cn(
        "relative grid size-[30px] shrink-0 cursor-pointer place-items-center rounded-[var(--radius)] text-[var(--muted-foreground)] outline-none [transition:background-color_.15s,color_.15s,opacity_.2s,transform_.35s_var(--ns-ease-rebound),scale_.35s_var(--ns-ease-rebound),translate_.35s_var(--ns-ease-rebound),rotate_.35s_var(--ns-ease-rebound)] hover:bg-[var(--accent)] hover:text-[var(--foreground)] focus-visible:ring-[length:var(--ns-focus-width,2px)] focus-visible:ring-[color:var(--ns-focus-color,var(--ring))] pointer-coarse:after:absolute pointer-coarse:after:-inset-[7px] pointer-coarse:after:content-[''] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
        className
      )}
      {...props}
    />
  )
})

export { FieldHelper, FieldIconButton, FieldLabel, FieldShell, useControllable, useFocusWithin }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/*
 * The shared parts: the rolling label every state change goes through, the check that draws
 * itself, the spinner and the live dot, and a timeline that schedules a component's steps and clears
 * them when it unmounts. Every class string is a plain literal (the shadcn CLI only rewrites those for
 * apps with tailwind.prefix). Keyframes (ns-*) live in the foundation CSS.
 *
 * Easing vocabulary (the design's names): press var(--ns-ease-press) for scale on press; roll
 * var(--ns-ease-reshape) for label rolls, menus and width morphs; pop var(--ns-ease-pop) for
 * icon swaps and checks landing; draw cubic-bezier(.6,0,.2,1) for strokes and sweeps; exit
 * cubic-bezier(.6,0,.9,.5) for things leaving.
 */

/** Runs on the client before paint, and as an effect on the server (React 18 warns about layout effects there). */
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect

/** Points one ref (callback or object) at `node`. */
function assignRef<T>(ref: React.Ref<T> | undefined, node: T | null) {
  if (typeof ref === "function") ref(node)
  else if (ref) (ref as React.MutableRefObject<T | null>).current = node
}

/** Sets every ref passed (callback or object), so a component can keep its own ref and forward the caller's. */
function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]) {
  const latest = React.useRef(refs)
  useIsomorphicLayoutEffect(() => {
    latest.current = refs
  })
  return React.useCallback((node: T | null) => {
    for (const ref of latest.current) assignRef(ref, node)
  }, [])
}

/** Schedules a component's steps; every pending step is cleared on clear() and on unmount. */
function useTimeline() {
  const timers = React.useRef<Set<ReturnType<typeof setTimeout>>>(new Set())
  React.useEffect(() => {
    const set = timers.current
    return () => {
      for (const t of set) clearTimeout(t)
      set.clear()
    }
  }, [])
  return React.useMemo(
    () => ({
      after(ms: number, fn: () => void) {
        const t = setTimeout(() => {
          timers.current.delete(t)
          fn()
        }, ms)
        timers.current.add(t)
        return t
      },
      clear() {
        for (const t of timers.current) clearTimeout(t)
        timers.current.clear()
      },
    }),
    []
  )
}

/** Resolves after `ms` (a minimum time a state shows, so a fast promise still reads). */
const wait = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

/**
 * A fixed-height window over a stack of rows; row `index` shows, the others roll past (.5s roll). Only
 * the showing row is in the accessibility tree, so the button's name is always the current label.
 */
function RollingLabel({ rows, index, size = "default", align = "center", fit = false, rowHeight, className }: { rows: readonly React.ReactNode[]; index: number; size?: "default" | "sm" | undefined; align?: "center" | "start" | undefined; /** Rows as wide as their own text (inside a window sized to the active row). */ fit?: boolean | undefined; /** A row height in px, for titles (overrides size). */ rowHeight?: number | undefined; className?: string | undefined }) {
  const height = rowHeight ?? (size === "sm" ? 18 : 20)
  return (
    <span data-slot="rolling-label" className={cn("relative block overflow-hidden", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), className)} style={rowHeight ? { height: rowHeight } : undefined}>
      <span
        className={cn("flex flex-col transition-transform duration-500 ease-[var(--ns-ease-reshape)] motion-reduce:transition-none", fit && (align === "center" ? "items-center" : "items-start"))}
        style={{ transform: `translateY(${-index * height}px)` }}
      >
        {rows.map((row, i) => (
          <span
            key={i}
            aria-hidden={i === index ? undefined : true}
            className={cn("flex shrink-0 items-center gap-2 whitespace-nowrap", !rowHeight && (size === "sm" ? "h-[18px]" : "h-5"), align === "center" ? "justify-center" : "justify-start", fit && "w-max")}
            style={rowHeight ? { height: rowHeight, lineHeight: `${rowHeight}px` } : undefined}
          >
            {row}
          </span>
        ))}
      </span>
    </span>
  )
}

/** The check that draws itself in (.45s draw after .15s) when `shown`. */
function DrawCheck({ shown, className }: { shown: boolean; className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-4 shrink-0", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path
        d="M20 6 9 17l-5-5"
        className="[stroke-dasharray:24] transition-[stroke-dashoffset] delay-150 duration-[450ms] ease-[cubic-bezier(.6,0,.2,1)] motion-reduce:transition-none"
        style={{ strokeDashoffset: shown ? 0 : 24 }}
      />
    </svg>
  )
}

/** The 14px spinner: an arc turning every .7s. */
function Spinner({ className }: { className?: string | undefined }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={cn("size-3.5 shrink-0 animate-[ns-spin_.7s_linear_infinite]", className)} fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" className="[stroke-dasharray:20_40]" />
    </svg>
  )
}

/** A 7px dot with a ring that keeps blooming out of it (live). */
function LiveDot({ className }: { className?: string | undefined }) {
  return (
    <span aria-hidden="true" className={cn("relative inline-flex size-[7px] shrink-0", className)}>
      <span className="absolute inset-0 animate-[ns-live_1.2s_ease-out_infinite] rounded-full bg-current" />
      <span className="relative size-full rounded-full bg-current" />
    </span>
  )
}

/**
 * Where overlays (menus, tooltips) portal to. Unset, they portal to document.body, where your
 * :root theme applies. Set it when the theme lives on an element instead of :root:
 *   <PortalContext.Provider value={element}>…</PortalContext.Provider>
 */
const PortalContext = React.createContext<HTMLElement | null>(null)

/** The container for an overlay's Portal: the provided element, else undefined (document.body). */
function usePortal() {
  return React.useContext(PortalContext) ?? undefined
}

/**
 * Writes text to the clipboard and resolves true only when it landed (falls back to a hidden textarea
 * where the async API is missing or blocked). Show "Copied" only on true.
 */
async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text)
      return true
    }
  } catch {
    // Blocked (permissions, an insecure origin): try the fallback below.
  }
  try {
    const area = document.createElement("textarea")
    area.value = text
    area.setAttribute("readonly", "")
    area.style.position = "fixed"
    area.style.opacity = "0"
    document.body.appendChild(area)
    area.select()
    const copied = document.execCommand("copy")
    area.remove()
    return copied
  } catch {
    return false
  }
}

/**
 * A callback ref that sets the inert attribute (React 18 has no inert prop): hidden panes and folded
 * sections stay out of the tab order and the accessibility tree.
 */
function inertRef(on: boolean) {
  return (node: HTMLElement | null) => {
    node?.toggleAttribute("inert", on)
  }
}

/** True while an IME is composing: key handlers that commit text ignore those keys. */
function composing(event: React.KeyboardEvent) {
  return event.nativeEvent.isComposing || event.keyCode === 229
}

/** True when focus is in a text field (single-key shortcuts stay out of the way). */
function typingInField() {
  const el = document.activeElement as HTMLElement | null
  return Boolean(el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable))
}

/** A label's text for the live region: the label itself when it is text, else `fallback`. */
function spoken(label: React.ReactNode, fallback: string) {
  return typeof label === "string" || typeof label === "number" ? String(label) : fallback
}

/** A polite live region that says `message` whenever it changes (label rolls, outcomes). */
function Announcer({ message }: { message: string }) {
  return (
    <span aria-live="polite" className="sr-only">
      {message}
    </span>
  )
}

const REDUCED = "(prefers-reduced-motion: reduce)"

/**
 * Whether motion should be calm right now: the OS asks for reduced motion, or `el` sits under
 * data-motion="off". For event handlers and effects (it reads the DOM).
 */
function prefersCalm(el?: Element | null) {
  if (typeof window === "undefined") return false
  return Boolean(window.matchMedia?.(REDUCED).matches || el?.closest('[data-motion="off"]'))
}

/**
 * Whether `el` sits in an RTL scope: the nearest `dir`, as Tailwind's `rtl:` styles read it, so a
 * dir="rtl" panel inside an LTR page (or the reverse) maps pointer and arrow keys the way it's drawn.
 */
function isRtl(el?: Element | null) {
  if (typeof window === "undefined") return false
  if (!el) return document.dir === "rtl"
  try {
    return el.matches(":dir(rtl)")
  } catch {
    return el.closest("[dir]")?.getAttribute("dir") === "rtl"
  }
}

/**
 * The one failure contract every action callback follows: it failed if it threw (handled by the caller),
 * or resolved `false`, a failed Response (`!res.ok`) or an object with an `error` (any value).
 */
function isFailedResult(result: unknown): boolean {
  if (result === false) return true
  if (typeof Response !== "undefined" && result instanceof Response) return !result.ok
  return typeof result === "object" && result !== null && "error" in result && (result as { error: unknown }).error != null
}

/** The message a failure carries, if it has one: a thrown Error's, or `{ error: "text" }`'s / `{ error: { message } }`'s. */
function failureMessage(reason: unknown): string {
  if (reason instanceof Error) return reason.message
  if (typeof reason === "object" && reason !== null && "error" in reason) {
    const e = (reason as { error: unknown }).error
    if (typeof e === "string") return e
    if (typeof e === "object" && e !== null && typeof (e as { message?: unknown }).message === "string") return (e as { message: string }).message
  }
  return ""
}

const noSubscribe = () => () => {}
/**
 * Now, on the client only: null on the server and during hydration (so both render the same in every
 * time zone), then the visitor's clock. For anything that shows "today" without a `today` prop.
 */
function useClientNow(): Date | null {
  const mounted = React.useSyncExternalStore(noSubscribe, () => true, () => false)
  const [now] = React.useState(() => (typeof window === "undefined" ? null : new Date()))
  return mounted ? (now ?? new Date()) : null
}

const subscribeReduced = (onChange: () => void) => {
  const mq = window.matchMedia?.(REDUCED)
  mq?.addEventListener("change", onChange)
  return () => mq?.removeEventListener("change", onChange)
}

/**
 * The OS reduced-motion preference for render, following changes. False on the server and during
 * hydration (so both render the same), then the real value.
 */
function useCalm() {
  return React.useSyncExternalStore(subscribeReduced, () => Boolean(window.matchMedia?.(REDUCED).matches), () => false)
}

export {
  failureMessage,
  isFailedResult,
  isRtl,
  useClientNow,
  Announcer,
  composing,
  copyText,
  DrawCheck,
